+    /**
+     * Check if the "arguments" variable in the given scope has been modified
+     * (has any write references like arguments[0] = ...).
+     */
+    private boolean isArgumentsModifiedInScope(
+        Scope scope, Map<Var, ReferenceCollection> referenceMap) {
+      Var argumentsVar = scope.getVar("arguments");
+      if (argumentsVar == null) {
+        return false;
+      }
+      ReferenceCollection argumentsReferences = referenceMap.get(argumentsVar);
+      if (argumentsReferences == null) {
+        return false;
+      }
+      // Check if arguments has any write references (property access on left side of assignment)
+      for (Reference ref : argumentsReferences.references) {
+        Node nameNode = ref.getNameNode();
+        Node parent = nameNode.getParent();
+        // Check for patterns like arguments[x] = ... or arguments.x = ...
+        if ((parent.getType() == Token.GETELEM || parent.getType() == Token.GETPROP)
+            && parent.getFirstChild() == nameNode) {
+          Node grandparent = parent.getParent();
+          // Check if this property access is being assigned to
+          if (grandparent.getType() == Token.ASSIGN && grandparent.getFirstChild() == parent) {
+            return true;
+          }
+        }
+      }
+      return false;
+    }

